// Package filestore stores attachment bytes on the local filesystem under opaque keys. | Package filestore
// 在不透明键下把附件字节保存到本地文件系统。
//
// It is the default messaging.BlobStore. The key is generated by the messaging package and never
// contains a user-supplied file name; every key segment is still validated here, so a caller that
// invents its own key cannot escape the root. | 它是默认的 messaging.BlobStore。键由 messaging 包生成，
// 绝不包含用户提供的文件名；这里仍会校验每个键段，因此自行构造键的调用方也无法逃出根目录。
package filestore

import (
	"context"
	"errors"
	"os"
	"path/filepath"
	"strings"

	"github.com/shibingli/yd/core/errx"
)

// Sentinel errors of the local store. | 本地存储的哨兵错误。
var (
	// ErrRootInvalid reports an empty or unusable root directory. | ErrRootInvalid 表示根目录为空或不可用。
	ErrRootInvalid = errx.New("attachment root is invalid | 附件根目录非法")
	// ErrKeyInvalid reports a key outside the safe segment alphabet. | ErrKeyInvalid 表示键包含不安全的段。
	ErrKeyInvalid = errx.New("attachment key is invalid | 附件键非法")
	// ErrWrite reports a failed write. | ErrWrite 表示写入失败。
	ErrWrite = errx.New("attachment write failed | 附件写入失败")
	// ErrRead reports a failed read. | ErrRead 表示读取失败。
	ErrRead = errx.New("attachment read failed | 附件读取失败")
	// ErrDelete reports a failed delete. | ErrDelete 表示删除失败。
	ErrDelete = errx.New("attachment delete failed | 附件删除失败")
)

// Store is a root-directory-backed blob store. | Store 是根目录支撑的字节存储。
type Store struct {
	// root is the absolute root directory. | root 是绝对根目录。
	root string
}

// New ensures root exists and returns a store rooted there. | New 确保 root 存在，并返回以它为根的存储。
func New(root string) (*Store, error) {
	root = strings.TrimSpace(root)
	if root == "" {
		return nil, ErrRootInvalid
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		return nil, errx.Wrap(err, ErrRootInvalid)
	}
	if err := os.MkdirAll(abs, 0o750); err != nil {
		return nil, errx.Wrap(err, ErrRootInvalid)
	}
	return &Store{root: abs}, nil
}

// Root returns the absolute root directory. | Root 返回绝对根目录。
func (s *Store) Root() string { return s.root }

// Put writes data under key. | Put 把 data 写入 key。
func (s *Store) Put(_ context.Context, key string, data []byte) error {
	target, err := s.resolve(key)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(target), 0o750); err != nil {
		return errx.Wrap(err, ErrWrite)
	}
	if err := os.WriteFile(target, data, 0o600); err != nil {
		return errx.Wrap(err, ErrWrite)
	}
	return nil
}

// Get reads the bytes stored under key. | Get 读取 key 下的字节。
func (s *Store) Get(_ context.Context, key string) ([]byte, error) {
	target, err := s.resolve(key)
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(target)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, errx.Wrap(err, ErrRead)
		}
		return nil, errx.Wrap(err, ErrRead)
	}
	return data, nil
}

// Delete removes key; a missing key is not an error. | Delete 删除 key；键不存在不算错误。
func (s *Store) Delete(_ context.Context, key string) error {
	target, err := s.resolve(key)
	if err != nil {
		return err
	}
	if err := os.Remove(target); err != nil && !errors.Is(err, os.ErrNotExist) {
		return errx.Wrap(err, ErrDelete)
	}
	return nil
}

// resolve validates every key segment and returns the absolute target. | resolve 校验每个键段并返回绝对目标路径。
func (s *Store) resolve(key string) (string, error) {
	key = strings.TrimSpace(key)
	if key == "" {
		return "", ErrKeyInvalid
	}
	segments := strings.Split(key, "/")
	for _, segment := range segments {
		if segment == "" || segment == "." || segment == ".." {
			return "", ErrKeyInvalid
		}
		for _, r := range segment {
			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
				r == '.' || r == '_' || r == '-' {
				continue
			}
			return "", ErrKeyInvalid
		}
	}
	target := filepath.Join(append([]string{s.root}, segments...)...)
	rel, err := filepath.Rel(s.root, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", ErrKeyInvalid
	}
	return target, nil
}
